/**
 * Exo GEMVER driver: mirrors PolyBench/C gemver.c but calls the Exo-generated kernel.
 *
 * Original authors:
 *   Louis-Noel Pouchet <pouchet.ohio-state.edu>
 *   Tomofumi Yuki <tomofumi.yuki.fr>
 *
 * Web address: http://polybench.sourceforge.net
 */
/* gemver.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemver.h"

/* Include the Exo-generated kernel header. */
#include "generated/gemver/gemver.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE *alpha,
		 DATA_TYPE *beta,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(u1,N,n),
		 DATA_TYPE POLYBENCH_1D(v1,N,n),
		 DATA_TYPE POLYBENCH_1D(u2,N,n),
		 DATA_TYPE POLYBENCH_1D(v2,N,n),
		 DATA_TYPE POLYBENCH_1D(w,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  DATA_TYPE fn = (DATA_TYPE)n;

  for (i = 0; i < n; i++)
    {
      u1[i] = i;
      u2[i] = ((i+1)/fn)/2.0;
      v1[i] = ((i+1)/fn)/4.0;
      v2[i] = ((i+1)/fn)/6.0;
      y[i] = ((i+1)/fn)/8.0;
      z[i] = ((i+1)/fn)/9.0;
      x[i] = 0.0;
      w[i] = 0.0;
      for (j = 0; j < n; j++)
        A[i][j] = (DATA_TYPE) (i*j % n) / n;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(w,N,n))
{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("w");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, w[i]);
  }
  POLYBENCH_DUMP_END("w");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

# Core Exo imports.
from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# High‑level GEMVER kernel in Exo.
# This matches the PolyBench reference algorithm but is written
# in a way that is friendly to optimization and scheduling.
@proc
def kernel_gemver(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # 1) Rank‑1 updates: A += u1*v1^T + u2*v2^T
    #    Access pattern is row‑major friendly: A[i0, j0] with j0 innermost.
    for i0 in seq(0, n):
        for j0 in seq(0, n):
            A[i0, j0] = A[i0, j0] + u1[i0] * v1[j0] + u2[i0] * v2[j0]

    # 2) x += beta * A^T * y
    #    Rewritten to traverse A by rows for better locality:
    #      for j: tmp1 = beta*y[j]
    #        for i: x[i] += A[j, i] * tmp1
    #    This is algebraically equivalent to the original:
    #      x[i] += beta * sum_j A[j, i] * y[j]
    for j1 in seq(0, n):
        tmp1: DATA_TYPE
        tmp1 = beta * y[j1]
        for i1 in seq(0, n):
            x[i1] = x[i1] + A[j1, i1] * tmp1

    # 3) x += z
    for i2 in seq(0, n):
        x[i2] = x[i2] + z[i2]

    # 4) w += alpha * A * x
    #    Computed as a matrix‑vector product with a scalar post‑scale:
    #      acc = sum_j A[i3, j3] * x[j3]
    #      w[i3] += alpha * acc
    for i3 in seq(0, n):
        acc: DATA_TYPE
        acc = 0.0
        for j3 in seq(0, n):
            acc += A[i3, j3] * x[j3]
        w[i3] = w[i3] + alpha * acc


# ---------------------------------------------------------------------------
# Scheduling / optimization.
# We now transform `kernel_gemver` to improve cache locality and
# expose parallelism.  The final, optimized procedure is rebound to
# the same Python name `kernel_gemver`, so the C driver sees the
# optimized version under the original symbol.
# ---------------------------------------------------------------------------

# Tile sizes chosen to fit well in L1/L2 caches on modern x86.
tile_i = 32
tile_j = 32

# 1) Tile the (i0, j0) nest in the rank‑1 update of A.
#    This improves spatial locality for A, v1, and v2, and lets us
#    parallelize across tiles of rows.
i0_loop = kernel_gemver.find_loop("i0")
kernel_gemver = divide_loop(kernel_gemver, i0_loop, tile_i, ("io0", "ii0"), tail="guard")

j0_loop = kernel_gemver.find_loop("j0")
kernel_gemver = divide_loop(kernel_gemver, j0_loop, tile_j, ("jo0", "ji0"), tail="guard")

# Reorder the inner tile loops so the execution order is:
#   for io0 (outer, parallel)
#     for jo0 (tile of columns)
#       for ii0
#         for ji0
# This preserves semantics (each (i0, j0) is still updated exactly once)
# while traversing A in cache‑friendly sub‑blocks.
kernel_gemver = reorder_loops(kernel_gemver, "ii0 jo0")

# Parallelize across row tiles of the rank‑1 update.  Each tile
# operates on a disjoint set of rows of A, so there are no races.
io0_loop = kernel_gemver.find_loop("io0")
kernel_gemver = parallelize_loop(kernel_gemver, io0_loop)

# 2) Parallelize the simple vector operations that are embarrassingly
#    parallel across i:
#    - x[i2] += z[i2]
#    - w[i3] += alpha * sum_j A[i3, j3] * x[j3]
#    In both cases, each loop iteration touches a distinct element of
#    the output vector, so OpenMP parallelization is safe.
i2_loop = kernel_gemver.find_loop("i2")
kernel_gemver = parallelize_loop(kernel_gemver, i2_loop)

i3_loop = kernel_gemver.find_loop("i3")
kernel_gemver = parallelize_loop(kernel_gemver, i3_loop)

# 3) Clean up any algebra and dead code after transformations.
kernel_gemver = simplify(kernel_gemver)
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(u1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(u2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(v2, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(w,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(z,  DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(u1),
	      POLYBENCH_ARRAY(v1),
	      POLYBENCH_ARRAY(u2),
	      POLYBENCH_ARRAY(v2),
	      POLYBENCH_ARRAY(w),
	      POLYBENCH_ARRAY(x),
	      POLYBENCH_ARRAY(y),
	      POLYBENCH_ARRAY(z));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to raw pointers. */
  kernel_gemver(/*ctxt=*/NULL, n,
                (DATA_TYPE*)&alpha,
                (DATA_TYPE*)&beta,
                (DATA_TYPE*)POLYBENCH_ARRAY(A),
                (DATA_TYPE*)POLYBENCH_ARRAY(u1),
                (DATA_TYPE*)POLYBENCH_ARRAY(v1),
                (DATA_TYPE*)POLYBENCH_ARRAY(u2),
                (DATA_TYPE*)POLYBENCH_ARRAY(v2),
                (DATA_TYPE*)POLYBENCH_ARRAY(w),
                (DATA_TYPE*)POLYBENCH_ARRAY(x),
                (DATA_TYPE*)POLYBENCH_ARRAY(y),
                (DATA_TYPE*)POLYBENCH_ARRAY(z));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(w)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(u1);
  POLYBENCH_FREE_ARRAY(v1);
  POLYBENCH_FREE_ARRAY(u2);
  POLYBENCH_FREE_ARRAY(v2);
  POLYBENCH_FREE_ARRAY(w);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(z);

  return 0;
}
