from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM


# Baseline GEMVER kernel written in Exo object code.
# The second phase (x update) is written to traverse A row-wise for
# better cache locality: we iterate over rows j and update all x[i].
@proc
def kernel_gemver_base(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # 1) Rank-1 updates to A: A = A + u1*v1^T + u2*v2^T
    for i0 in seq(0, n):
        for j0 in seq(0, n):
            A[i0, j0] = A[i0, j0] + u1[i0] * v1[j0] + u2[i0] * v2[j0]

    # 2) x = x + beta * A^T * y
    #    Written as:
    #      for j1:   tmp = beta * y[j1]
    #        for i1: x[i1] += tmp * A[j1, i1]
    #    so that we walk A row-wise (good spatial locality).
    for j1 in seq(0, n):
        tmp: DATA_TYPE
        tmp = beta * y[j1]
        for i1 in seq(0, n):
            x[i1] = x[i1] + tmp * A[j1, i1]

    # 3) x = x + z
    for i2 in seq(0, n):
        x[i2] = x[i2] + z[i2]

    # 4) w = w + alpha * A * x
    for i3 in seq(0, n):
        for j2 in seq(0, n):
            w[i3] = w[i3] + alpha * A[i3, j2] * x[j2]


# ---------------------------------------------------------------------------
# Scheduling: add OpenMP-style parallelism to the main loops.
#  - Phase 1: parallel over rows i0 of A.
#  - Phase 2: for each row j1, parallel over elements of x (loop i1).
#  - Phase 4: parallel over rows i3 when forming w.
# Exo's effect analysis ensures these parallelizations are race-free.
# ---------------------------------------------------------------------------

kernel_gemver = kernel_gemver_base

# Parallelize phase 1 outer loop over i0.
i0 = kernel_gemver.find_loop("i0")
kernel_gemver = parallelize_loop(kernel_gemver, i0)

# Parallelize phase 2 inner loop over i1 (for each fixed j1).
i1 = kernel_gemver.find_loop("i1")
kernel_gemver = parallelize_loop(kernel_gemver, i1)

# Parallelize phase 4 outer loop over i3.
i3 = kernel_gemver.find_loop("i3")
kernel_gemver = parallelize_loop(kernel_gemver, i3)

# Optional simplification pass to clean up the scheduled IR.
kernel_gemver = simplify(kernel_gemver)
