from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Reference GEMVER kernel: matches the PolyBench/C semantics.
@proc
def kernel_gemver(
    n: size,
    alpha: DATA_TYPE,
    beta: DATA_TYPE,
    A: DATA_TYPE[n, n] @ DRAM,
    u1: DATA_TYPE[n] @ DRAM,
    v1: DATA_TYPE[n] @ DRAM,
    u2: DATA_TYPE[n] @ DRAM,
    v2: DATA_TYPE[n] @ DRAM,
    w: DATA_TYPE[n] @ DRAM,
    x: DATA_TYPE[n] @ DRAM,
    y: DATA_TYPE[n] @ DRAM,
    z: DATA_TYPE[n] @ DRAM,
):
    # 1) Rank-2 update: A = A + u1*v1^T + u2*v2^T
    for i in seq(0, n):
        for j in seq(0, n):
            A[i, j] = A[i, j] + u1[i] * v1[j] + u2[i] * v2[j]

    # 2) x = x + beta * A^T * y
    for i in seq(0, n):
        for j in seq(0, n):
            x[i] = x[i] + beta * A[j, i] * y[j]

    # 3) x = x + z
    for i in seq(0, n):
        x[i] = x[i] + z[i]

    # 4) w = w + alpha * A * x
    for i in seq(0, n):
        for j in seq(0, n):
            w[i] = w[i] + alpha * A[i, j] * x[j]


# ----------------------------------------------------------------------
# Scheduling: improve data locality and expose parallelism.
# ----------------------------------------------------------------------

# Normalize the IR a bit before transformation.
kernel_gemver = simplify(kernel_gemver)

# -----------------------------
# Tile and parallelize phase 1: update of A.
# We perform 2D blocking over (i, j) to improve cache reuse of A and the
# vectors v1, v2. The outer tile loops are then parallelized.
# -----------------------------

# Split the first i-loop (over A) into tiles of size 64: i -> (io0, ii0).
kernel_gemver = divide_loop(kernel_gemver, "i #0", 64, ("io0", "ii0"), tail="guard")

# Split the corresponding inner j-loop into tiles of size 64: j -> (jo0, jj0).
kernel_gemver = divide_loop(kernel_gemver, "j #0", 64, ("jo0", "jj0"), tail="guard")

# Reorder loops to iterate tiles of rows and columns first:
#   original: for io0: for ii0: for jo0: for jj0:
#   desired:  for io0: for jo0: for ii0: for jj0:
kernel_gemver = reorder_loops(kernel_gemver, "ii0 jo0")

# Clean up any algebra introduced by tiling.
kernel_gemver = simplify(kernel_gemver)

# Parallelize across tiles of rows in the first phase. Different io0
# iterations touch disjoint rows of A and independent entries of u1/u2.
kernel_gemver = parallelize_loop(kernel_gemver, "io0")

# -----------------------------
# Parallelize phase 2: x = x + beta * A^T * y
# We parallelize across i; each iteration reduces only into x[i].
# -----------------------------
kernel_gemver = parallelize_loop(kernel_gemver, "i #0")

